/**
 * The single registry of occasion sections. Every release's pages hang off these slugs:
 * /occasions/[id]/<slug>. Labels live in the `nav` i18n namespace (nav.occasion.<key>).
 * Feature agents create the pages; they do not edit this file.
 */
export type OccasionNavItem = { key: string; slug: string };
export type OccasionNavGroup = { key: string; items: OccasionNavItem[] };

